<?php
declare(strict_types=1); require __DIR__.'/config.php';
$station=trim((string)($_GET['station']??'')); $year=trim((string)($_GET['year']??'')); $season=trim((string)($_GET['season']??''));
if (($station!==''&&!preg_match('/^[0-9]+$/',$station)) || ($year!==''&&(!preg_match('/^[0-9]{4}$/',$year)|| (int)$year<1900)) || ($season!==''&&!in_array($season,['hiver','printemps','ete','automne'],true))) { http_response_code(422); exit('Filtres invalides.'); }
$sql='SELECT s.Nom,s.Ville,m.idstation,m.annee,m.saison,m.temperature,m.pluie FROM mesure m INNER JOIN station s ON s.Idstation=m.idstation WHERE (? = \'\' OR m.idstation=?) AND (? = \'\' OR m.annee=?) AND (? = \'\' OR m.saison=?) ORDER BY m.annee DESC,s.Nom,FIELD(m.saison,\'hiver\',\'printemps\',\'ete\',\'automne\')';
$stmt=$db->prepare($sql); $sid=$station; $yr=$year; $stmt->bind_param('ssssss',$sid,$sid,$yr,$yr,$season,$season); $stmt->execute(); $rows=$stmt->get_result();
$stations=$db->query('SELECT Idstation,Nom,Ville FROM station ORDER BY Ville,Nom');
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Historique — Fedi Climat</title><link rel="stylesheet" href="fedi.css"></head><body><header><a class="brand" href="index.php"><span>F</span> Fedi Climat</a><nav><a href="index.php">Accueil</a><a href="mesure.php">Ajouter</a><a href="moyenne.php">Moyennes</a></nav></header><main class="content wide"><p class="eyebrow">Exploration des relevés</p><h1>Historique des mesures</h1><form method="get" class="filters"><label for="station">Station</label><select id="station" name="station"><option value="">Toutes</option><?php while($s=$stations->fetch_assoc()):?><option value="<?=(int)$s['Idstation']?>" <?= $station===(string)$s['Idstation']?'selected':''?>><?=h($s['Nom'].' — '.$s['Ville'])?></option><?php endwhile;?></select><label for="year">Année</label><input id="year" name="year" type="number" min="1900" max="<?= (int)date('Y') ?>" value="<?=h($year)?>"><label for="season">Saison</label><select id="season" name="season"><option value="">Toutes</option><?php foreach(['hiver'=>'Hiver','printemps'=>'Printemps','ete'=>'Été','automne'=>'Automne'] as $k=>$v):?><option value="<?=h($k)?>" <?=$season===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select><button class="button">Filtrer</button><a href="consultation.php">Effacer</a></form><div class="table-wrap"><table><thead><tr><th>Station</th><th>Ville</th><th>Année</th><th>Saison</th><th>Température</th><th>Pluie (mm)</th></tr></thead><tbody><?php if($rows->num_rows===0):?><tr><td colspan="6">Aucune mesure trouvée.</td></tr><?php else:while($r=$rows->fetch_assoc()):?><tr><td><?=h($r['Nom'])?></td><td><?=h($r['Ville'])?></td><td><?=(int)$r['annee']?></td><td><?=h(ucfirst($r['saison']))?></td><td><?=number_format((float)$r['temperature'],2,',',' ')?> °C</td><td><?=(int)$r['pluie']?></td></tr><?php endwhile;endif;?></tbody></table></div></main><footer>Fedi Climat</footer></body></html>